import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
};

// ============================================================
// SPREADSHEET — YouTube scraping for AI video ideation
// ============================================================
const SCENE_DURATION = 150;

const SpreadsheetCard: React.FC<{
  fillProgress: number;
}> = ({ fillProgress }) => {
  const rows: [string, string, string][] = [
    ["I built an AI agent in 10 minutes", "2.4M", "9.8"],
    ["The truth about GPT-5 for coding", "1.8M", "9.5"],
    ["Why Claude beats ChatGPT in 2025", "1.3M", "9.2"],
    ["I replaced my team with AI agents", "2.1M", "9.6"],
    ["The AI tools nobody talks about", "2.7M", "9.9"],
  ];

  return (
    <div
      style={{
        width: 1600,
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 36,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        boxShadow: `0 40px 100px rgba(0,0,0,0.5)`,
      }}
    >
      {/* Title bar */}
      <div
        style={{
          padding: "44px 56px",
          borderBottom: `1px solid ${COLORS.border}`,
          display: "flex",
          alignItems: "center",
          gap: 28,
        }}
      >
        <div
          style={{
            width: 96,
            height: 96,
            borderRadius: 20,
            background: "rgba(52, 168, 83, 0.15)",
            border: "1.5px solid rgba(52, 168, 83, 0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 52,
            fontWeight: 800,
            color: "#34A853",
          }}
        >
          ⊞
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 30,
              color: COLORS.textSubtle,
              fontWeight: 500,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
            }}
          >
            YouTube Scraper
          </div>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 52,
              color: COLORS.text,
              fontWeight: 700,
              letterSpacing: "-0.02em",
            }}
          >
            ai_video_ideas.csv
          </div>
        </div>
      </div>

      {/* Column headers */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "100px 1fr 240px 200px",
          padding: "28px 56px",
          background: "rgba(255,255,255,0.03)",
          borderBottom: `1px solid ${COLORS.border}`,
          gap: 28,
        }}
      >
        {["#", "Video title", "Views", "Idea score"].map((h, i) => (
          <div
            key={i}
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 26,
              color: COLORS.textSubtle,
              fontWeight: 600,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
            }}
          >
            {h}
          </div>
        ))}
      </div>

      {/* Data rows */}
      <div style={{ padding: "0 56px" }}>
        {rows.map((row, i) => {
          const rowProgress = interpolate(
            fillProgress,
            [i / rows.length, (i + 1) / rows.length],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          return (
            <div
              key={i}
              style={{
                display: "grid",
                gridTemplateColumns: "100px 1fr 240px 200px",
                padding: "36px 0",
                borderBottom:
                  i < rows.length - 1 ? `1px solid ${COLORS.border}` : "none",
                gap: 28,
                opacity: rowProgress,
                transform: `translateX(${interpolate(
                  rowProgress,
                  [0, 1],
                  [-20, 0]
                )}px)`,
              }}
            >
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 32,
                  color: COLORS.textSubtle,
                  fontWeight: 500,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {i + 1}
              </div>
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 34,
                  color: COLORS.text,
                  fontWeight: 600,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {row[0]}
              </div>
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 32,
                  color: COLORS.textMuted,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {row[1]}
              </div>
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 32,
                  color: COLORS.orange,
                  fontWeight: 700,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                ★ {row[2]}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const Scene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Rows fill in over 50 frames (2s @ 25fps), starting from frame 0
  const fillProgress = interpolate(frame, [0, 50], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        fontFamily: "Inter, sans-serif",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <SpreadsheetCard fillProgress={fillProgress} />
    </AbsoluteFill>
  );
};

export const durationInFrames = SCENE_DURATION;

export default Scene;
